    CollectedTypeAlias::Omit { .. }
    | CollectedTypeAlias::Pick { .. }
    | CollectedTypeAlias::Partial { .. }
    | CollectedTypeAlias::Required { .. }
    | CollectedTypeAlias::Union { .. }
    | CollectedTypeAlias::LiteralUnion { .. } => {}
}

