            return None;
        }
        let props = self.ts_type_to_collected(&annotation.type_annotation);
        Some(CollectedType::Function {
            type_params: Vec::new(),
            params: vec![props],
            param_names: vec![None],
            param_kinds: Vec::new(),
            return_type: Box::new(CollectedType::Unknown),
        })
    }

