    fn record_result_of<'a>(
        &mut self,
        name: &str,
        type_parameters: Option<&TSTypeParameterDeclaration<'a>>,
        return_type: Option<&TSTypeAnnotation<'a>>,
        body: Option<&FunctionBody<'a>>,
