                    pending.name,
                    pending.callee.name.clone(),
                    self.file_path.clone(),
                    pending.span.start,
                    pending.span.end,
                    DetectionRule::FactoryResult,
                )
                .with_wrapper_callee(pending.callee)
                .with_doc(pending.description, pending.tags),
            );
        }
    }

