}
RUNS = 9
for corpus, src in SRCS.items():
    res = {k: [] for k in BINS}
    for _ in range(RUNS):
        for label, binary in BINS.items():
            out = subprocess.run(["python3", "-I", "/tmp/claude-501/t155/one_run.py", binary, src], capture_output=True, text=True).stdout.split()
            res[label].append((float(out[0]), float(out[1])))
    for label, rows in res.items():
        wall = statistics.median(r[0] for r in rows)
        rss = statistics.median(r[1] for r in rows)
